@extends('layouts.app')@section('title','Keranjang')@section('content')<div class="pagehead"><h1>Keranjang Belanja</h1><a class="btn light" href="{{ route('shop') }}">Lanjut Belanja</a></div><div class="panel">@if(count($cart))<form method="POST" action="{{ route('cart.update') }}">@csrf @method('PATCH')<div class="tablewrap"><table><tr><th>Produk</th><th>Harga</th><th>Jumlah</th><th>Subtotal</th><th></th></tr>@php($total=0)@foreach($cart as $id=>$qty)@php($p=$products[$id]??null)@if($p)@php($sub=$p->price*$qty)@php($total+=$sub)<tr><td>{{ $p->name }}</td><td>Rp {{ number_format($p->price,0,',','.') }}</td><td><input type="number" name="qty[{{ $id }}]" value="{{ $qty }}" min="1" max="{{ $p->stock }}" style="width:80px;padding:8px;border:1px solid #ddd;border-radius:8px"></td><td>Rp {{ number_format($sub,0,',','.') }}</td><td><button form="remove-{{ $id }}" class="btn red sm">Hapus</button></td></tr>@endif@endforeach</table></div><div style="text-align:right;margin-top:16px"><h2>Total: Rp {{ number_format($total,0,',','.') }}</h2><button class="btn light">Perbarui Keranjang</button><a class="btn" href="{{ route('checkout') }}">Checkout</a></div></form>@foreach($cart as $id=>$qty)<form id="remove-{{ $id }}" method="POST" action="{{ route('cart.remove',$id) }}">@csrf @method('DELETE')</form>@endforeach @else<div class="empty">Keranjang masih kosong 🛒<p><a class="btn" href="{{ route('shop') }}">Mulai Belanja</a></p></div>@endif</div>@endsection